using Ets2u.Core.Mods;
using Ets2u.Core.Sii;

namespace Ets2u.Core.Features;

/// <summary>
/// Overrides def/damage_data.sii. On: every damage and wear value is 0. Off: the stock file.
/// Built from the player's own game files, so it follows game updates.
/// </summary>
public static class NoDamage
{
    public const string GamePath = "def/damage_data.sii";
    const string Unit = "vehicle_damage_data";

    public static readonly ModSpec Mod = new(
        "ets2u_nodamage", "ETS2 Utilities: No damage", "physics",
        "Generated by ETS2 Utilities. Turns truck, coach, trailer and cargo damage and wear on or off.\n" +
        "Change it from the app, not by hand.");

    static readonly string[] DamageSuffixes = ["_coef", "_factor", "_dmg", "_ratio", "_wear", "_wear_unfixable"];

    public static bool IsDamageKey(string key) => DamageSuffixes.Any(key.EndsWith);

    /// <summary>The damage_data.sii to ship: stock values when off, zeros when on.</summary>
    public static byte[] Build(byte[] stock, bool enabled)
    {
        if (!enabled) return stock;
        var doc = SiiDocument.Parse(stock);
        var unit = doc.FindUnit(Unit) ?? throw new FormatException($"No {Unit} unit in {GamePath}.");
        foreach (var key in unit.Keys.Where(IsDamageKey).ToList())
            doc.SetValue(unit, key, "0.0");
        return doc.ToBytes();
    }

    public static byte[] BuildMod(byte[] stock, bool enabled) =>
        ScsModBuilder.Build(Mod, new Dictionary<string, byte[]> { [GamePath] = Build(stock, enabled) });

    /// <summary>Whether a built mod currently has damage switched off (all damage keys zero).</summary>
    public static bool? ReadState(byte[] scs)
    {
        var file = ScsModBuilder.Read(scs, GamePath);
        if (file is null) return null;
        var doc = SiiDocument.Parse(file);
        var unit = doc.FindUnit(Unit);
        if (unit is null) return null;
        return unit.Keys.Where(IsDamageKey).All(k => double.TryParse(doc.GetValue(unit, k),
            System.Globalization.NumberStyles.Float, System.Globalization.CultureInfo.InvariantCulture, out var v) && v == 0);
    }
}
